module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0]dout_parallel,
    output reg dout_valid
);
	reg [3:0] cnt;

	always @(posedge clk, negedge rst_n) begin
	    if(!rst_n)
	        cnt <= 0;
	    else if(cnt == 7 && din_valid)
	        cnt <= 0;
	    else if(din_valid)
	        cnt <= cnt + 1;
	end

	always@(posedge clk) begin
	    if(cnt != 0)
	        dout_parallel[cnt-1] <= din_serial;
	        dout_parallel <= 8'd0;
	end

	always@(*) begin
	    if(cnt == 7 && din_valid) dout_valid = 1'b1; else dout_valid = 1'b0;
	end
endmodule
